#pragma warning disable CS0169 // The field is never used
struct A<T>
{
    A<A<T>> x;
}

struct B<T>
{
    A<B<T>> x;
}

struct C<T>
{
    D<T> x;
}
struct D<T>
{
    C<D<T>> x;
}

